"""A tiny DQN in NumPy: experience replay + target network vs naive online Q-learning with the same network.

Task: a point mass on [0, 1] must reach x >= 1. State (x, v); actions push -1 / 0 / +1; reward -1 per step;
episodes end at the goal or after 100 steps. Network: 2 -> 32 (ReLU) -> 3 Q-values, trained on the squared TD error.
"""
import numpy as np
def env_step(s, a):
    x, v = s; v = np.clip(0.9 * v + 0.02 * (a - 1), -0.1, 0.1); x = np.clip(x + v, 0, 1)
    return np.array([x, v]), -1.0, x >= 1.0
class Net:
    def __init__(self, rng):
        self.W1 = rng.normal(0, 0.5, (2, 32)); self.b1 = np.zeros(32); self.W2 = rng.normal(0, 0.1, (32, 3)); self.b2 = np.zeros(3)
    def q(self, S):
        h = np.maximum(0, (S * [1, 10]) @ self.W1 + self.b1); return h @ self.W2 + self.b2, h
    def copy(self, o): self.W1, self.b1, self.W2, self.b2 = o.W1.copy(), o.b1.copy(), o.W2.copy(), o.b2.copy()
    def train(self, S, A, Y, lr):
        Q, h = self.q(S); err = np.zeros_like(Q); err[np.arange(len(A)), A] = Q[np.arange(len(A)), A] - Y
        gW2 = h.T @ err / len(A); gb2 = err.mean(0); dh = (err @ self.W2.T) * (h > 0)
        gW1 = (S * [1, 10]).T @ dh / len(A); gb1 = dh.mean(0)
        for p, gp in ((self.W1, gW1), (self.b1, gb1), (self.W2, gW2), (self.b2, gb2)): p -= lr * np.clip(gp, -1, 1)
def run(dqn, seed, episodes=300, gamma=0.99):
    rng = np.random.default_rng(seed); net, tgt = Net(rng), Net(rng); tgt.copy(net)
    buf, steps_list, t, qs = [], [], 0, []
    for ep in range(episodes):
        s = np.array([0.0, 0.0]); eps = max(0.05, 1 - ep / 150)
        for n in range(1, 101):
            a = int(rng.integers(3)) if rng.random() < eps else int(np.argmax(net.q(s[None])[0]))
            s2, r, done = env_step(s, a); t += 1
            if dqn:
                buf.append((s, a, r, s2, done)); buf = buf[-5000:]
                if len(buf) >= 64:
                    idx = rng.integers(len(buf), size=32); B = [buf[i] for i in idx]
                    S = np.array([b[0] for b in B]); A = np.array([b[1] for b in B]); R = np.array([b[2] for b in B])
                    S2 = np.array([b[3] for b in B]); D = np.array([b[4] for b in B])
                    Y = R + gamma * (1 - D) * tgt.q(S2)[0].max(1)            # target network
                    net.train(S, A, Y, 0.05)
                if t % 200 == 0: tgt.copy(net)
            else:
                Y = r + gamma * (0 if done else net.q(s2[None])[0].max())     # same network, consecutive samples
                net.train(s[None], np.array([a]), np.array([Y]), 0.05)
            s = s2
            if done: break
        steps_list.append(n); qs.append(net.q(np.array([[0.0, 0.0]]))[0].max())
    return np.array(steps_list), np.array(qs)
true_q = -(1 - 0.99 ** 13.3) / 0.01
for dqn in (True, False):
    res = [run(dqn, sd) for sd in range(3)]
    steps = np.array([r[0] for r in res]); q0 = np.array([r[1][-50:].mean() for r in res])
    print(f"{'DQN (replay + target net)' if dqn else 'naive online Q-learning':<27} steps to goal, last 50 episodes: {steps[:, -50:].mean():5.1f}"
          f" | predicted Q(start) per seed: {np.round(q0, 1)}")
print(f"True Q(start) for a ~13-step path with gamma 0.99: {true_q:.1f}.")
print("Both greedy policies reach the goal (only the ranking of actions matters), but without replay and a target")
print("network the Q-values themselves blow up: the network chases its own moving, correlated targets.")
